from itertools import combinations
from hashlib import sha256

r,q,i,j=5,6,2,2
rect=(2,2)

def norm(p):
    return tuple(x for x in p if x)

def parts_box(r,q,lo=()):
    # all partitions in q^r containing lo, generated recursively
    out=[]
    def rec(prev, k, cur):
        if k==r:
            p=norm(tuple(cur))
            if all((p[t] if t<len(p) else 0) >= (lo[t] if t<len(lo) else 0) for t in range(max(len(p),len(lo)))):
                out.append(p)
            return
        lower=lo[k] if k<len(lo) else 0
        for x in range(prev,lower-1,-1):
            rec(x,k+1,cur+[x])
    rec(q,0,[])
    return out

def contains(p, mu):
    return all((p[t] if t<len(p) else 0)>=(mu[t] if t<len(mu) else 0) for t in range(max(len(p),len(mu))))

def horiz(nu,mu):
    # nu/mu horizontal iff nu_1 >= mu_1 >= nu_2 >= mu_2 ...
    L=max(len(nu),len(mu))
    if not contains(nu,mu): return False
    for k in range(L):
        muk=mu[k] if k<len(mu) else 0
        nunext=nu[k+1] if k+1<len(nu) else 0
        if muk<nunext: return False
    return True

def sz(p): return sum(p)
def ps(p): return ''.join(map(str,p)) or '0'

P=parts_box(r,q,rect)
bydeg={}
for p in P: bydeg.setdefault(sz(p),[]).append(p)
for d in bydeg: bydeg[d].sort(reverse=True)

# The two source formula intervals, checked directly by containment.
a=min(q-i,r-j); b=min(i,j)
top1=(i+a,)*b+(i,)*(j-b)
top2=(i,)*j+(b,)*a
F1=[p for p in P if contains(p,rect) and contains(top1,p)]
F2=[p for p in P if contains(p,rect) and contains(top2,p)]

# Pieri rows at each degree: h_k*s_mu, 1<=k<=q.
rowsbydeg={d:[] for d in bydeg}
for mu in P:
    for k in range(1,q+1):
        d=sz(mu)+k
        if d not in bydeg: continue
        row=[0]*len(bydeg[d])
        for c,nu in enumerate(bydeg[d]):
            if horiz(nu,mu): row[c]=1
        if any(row): rowsbydeg[d].append((mu,k,row))

def certify(F):
    allok=True; records=[]; digest_parts=[]
    for d,cols in sorted(bydeg.items()):
        free={p for p in F if sz(p)==d}
        targets=[c for c,p in enumerate(cols) if p not in free]
        # Mutable exact row system. Each row includes provenance for reproducibility.
        rows=[[mu,k,v[:]] for mu,k,v in rowsbydeg[d]]
        piv=[]
        for col in targets:
            found=None
            for z,R in enumerate(rows):
                if abs(R[2][col])==1:
                    found=z; break
            if found is None:
                allok=False; break
            rows[0],rows[found]=rows[found],rows[0]
            pivrow=rows[0]
            if pivrow[2][col]==-1:
                pivrow[2]=[-x for x in pivrow[2]]
            # Clear this target column in every other row, including previous pivots
            for z in range(1,len(rows)):
                c=rows[z][2][col]
                if c:
                    rows[z][2]=[x-c*y for x,y in zip(rows[z][2],pivrow[2])]
            # retain pivot row at front; rotate it behind already-pivoted rows is unnecessary
            piv.append((ps(pivrow[0]),pivrow[1],ps(cols[col])))
            # move pivot row to stable prefix position
            rows.insert(len(piv)-1,rows.pop(0))
        # After target elimination all nonpivot rows must be zero: otherwise a free relation remains.
        residual=[]
        for R in rows[len(piv):]:
            if any(R[2]): residual.append((ps(R[0]),R[1]))
        ok=(len(piv)==len(targets) and not residual)
        allok=allok and ok
        records.append((d,len(cols),len(rowsbydeg[d]),len(free),len(targets),len(piv),len(residual),ok))
        digest_parts.extend([str(x) for x in piv])
    return allok,records,sha256((';'.join(digest_parts)).encode()).hexdigest()

for name,F in [('F1',F1),('F2',F2)]:
    ok,records,dig=certify(F)
    print(name,'family=',[ps(x) for x in F])
    print(name,'family_size=',len(F),'certificate_ok=',ok,'pivot_digest=',dig)
    print(name,'degree_blocks=(degree,columns,pieri_rows,free,target,pivots,residual,ok)')
    for x in records: print(x)
print('total_columns=',len(P),'total_pieri_rows=',sum(len(x) for x in rowsbydeg.values()))
print('a,b,N=',a,b,len(F1))
